-- ==========================================================================
-- B4 FOLLOW-ON FIX (fdp): fdp: duplicate question rewritten into a new question
--
-- Courses: fdp. Rows changed: 1; rows inserted: 0.
-- Source: tools/answer-length-audit/fixes/fdp.json (every item, its verdict and
-- its reason, old and new text side by side); generated by
-- tools/answer-length-audit/fix.py sql fdp. Runs AFTER the 29 B4 length files
-- and any earlier fix file: every guard below is the text those leave behind.
--
-- GUARDS. Each changed row must match its OLD prompt, explanation and options
-- (md5) and answer_index exactly (then it is updated) or its NEW ones (already
-- applied, left alone). Anything else raises and the transaction rolls back.
-- Each insert must be absent (inserted) or present with the same text (left).
-- Each course ends at its asserted question count. SAFE TO RE-RUN.
-- ==========================================================================

do $$
declare
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_total   integer;
begin

  -- fdp beginner final - ord 14
  select case when md5(prompt) = '10ec7a3613d45e757f565ce970c2d83c' and md5(coalesce(explanation, '')) = '7295bce4364099414313048968ba42ab' and md5(options::text) = md5('["A count of 1 means the engine could not aggregate the distributions it was given, so the gas figure is a sum of low cases in the way the oil column of 80.0000 MMbbl is.", "The count decides the unit: one gas row stays in Bcf, while two or more would be totalled onto a barrel of oil equivalent basis.", "A fluid with one row has no aggregation in it, so 70.0000 Bcf is a single reservoir estimate carried through rather than a sum of anything.", "A count of 1 marks the fluid as unverified, because the engine will not label a column P50 until it has at least two independent estimates of the same volume to read it from."]'::jsonb::text) and answer_index = 2 then 'old'
              when md5(prompt) = '2deb5c2068b85af2255f6e4b5828755e' and md5(coalesce(explanation, '')) = '189a8580d48ce8d29e1d5029f53b0edb' and md5(options::text) = md5('["Because the gas row count of 1 is too few rows for the engine to aggregate into a converted total.", "Because the engine converts only condensate to oil equivalent, and gas needs a recovery factor below 0.650000 before it can be put on a barrel basis.", "Because converting gas to barrels equivalent is a commercial assumption about heating value and price, which somebody has to make and defend.", "Because a barrel equivalent is a P50 quantity only, and the table also carries P90 and P10 columns that no conversion factor can be applied to at all."]'::jsonb::text) and answer_index = 2 then 'new'
              else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'fdp' and tier = 'beginner' and scope = 'final' and module_key is not distinct from null and ord = 14 and active;
  if v_state is null then raise exception 'B4 fix fdp refused: no row for fdp beginner final - ord 14'; end if;
  if v_state = 'other' then raise exception 'B4 fix fdp refused: fdp beginner final - ord 14 matches neither its current nor its fixed form'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'A manager asks the studio for EGINA''s reserves as one total on a barrel of oil equivalent basis. Why does the reserves table leave that figure to a person?', options = '["Because the gas row count of 1 is too few rows for the engine to aggregate into a converted total.", "Because the engine converts only condensate to oil equivalent, and gas needs a recovery factor below 0.650000 before it can be put on a barrel basis.", "Because converting gas to barrels equivalent is a commercial assumption about heating value and price, which somebody has to make and defend.", "Because a barrel equivalent is a P50 quantity only, and the table also carries P90 and P10 columns that no conversion factor can be applied to at all."]'::jsonb,
           answer_index = 2, explanation = 'Gas can be expressed on a barrel of oil equivalent basis, and the factor is a commercial assumption about heating value and price. The table keeps oil in MMbbl and gas in Bcf, returns one total per fluid, and leaves the combining to a person who will say what factor they used. Condensate is kept apart from oil too.'
     where app_slug = 'fdp' and tier = 'beginner' and scope = 'final' and module_key is not distinct from null and ord = 14 and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'B4 fix fdp refused: fdp beginner final - ord 14 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_total from public.academy_quiz_questions where app_slug = 'fdp' and active;
  if v_total <> 396 then raise exception 'B4 fix fdp refused: fdp holds % active questions, expected 396', v_total; end if;
  raise notice 'B4 fix fdp: % of 1 rows written, the rest already carried the fixed text', v_updated;
end $$;
